import pandas as pd
import numpy as np
import json

# Load data
sharadar_tickers = pd.read_csv('/home/ubuntu/data/sharadar/SHARADAR_TICKERS_2_7ef16c1ffc4112bb028c13f3e3743955.csv')
sharadar_sep = pd.read_csv('/home/ubuntu/data/sharadar/SHARADAR_SEP_2_0afbc06bfa7d2d5ebd28c43e0940ec30.csv', usecols=['ticker','date','closeadj'])
sharadar_sf1 = pd.read_csv('/home/ubuntu/data/sharadar/SHARADAR_SF1_3_15e102612341e619fb9bbd8f089942ea.csv')

# Filter data
active_us_common_stocks = sharadar_tickers[(sharadar_tickers['table']=='SEP') & (sharadar_tickers['isdelisted']=='N') & (sharadar_tickers['category']=='Domestic Common Stock')]
sharadar_sep = sharadar_sep[sharadar_sep['ticker'].isin(active_us_common_stocks['ticker'])]
sharadar_sf1 = sharadar_sf1[sharadar_sf1['ticker'].isin(active_us_common_stocks['ticker'])]

# Pivot SEP data
sharadar_sep_pivot = sharadar_sep.pivot(index='date', columns='ticker', values='closeadj')

# Filter SF1 data
sharadar_sf1 = sharadar_sf1[sharadar_sf1['dimension']=='ARQ']

# Merge data
merged_data = pd.merge(sharadar_sep_pivot.reset_index(), sharadar_sf1, on='ticker', how='left')

# Compute Piotroski F-score
def compute_piotroski_f_score(row):
    if row['roe_lag'] > 0:
        roe = 1
    elif row['roe_lag'] < 0:
        roe = 0
    else:
        roe = np.inf

    if row['roi_lag'] > 0:
        roi = 1
    elif row['roi_lag'] < 0:
        roi = 0
    else:
        roi = np.inf

    if row['debt_equity_lag'] < 1:
        debt_equity = 1
    elif row['debt_equity_lag'] > 1:
        debt_equity = 0
    else:
        debt_equity = np.inf

    if row['cash_flow_lag'] > 0:
        cash_flow = 1
    elif row['cash_flow_lag'] < 0:
        cash_flow = 0
    else:
        cash_flow = np.inf

    if row['sales_growth_lag'] > 0:
        sales_growth = 1
    elif row['sales_growth_lag'] < 0:
        sales_growth = 0
    else:
        sales_growth = np.inf

    if row['asset_turnover_lag'] > 0:
        asset_turnover = 1
    elif row['asset_turnover_lag'] < 0:
        asset_turnover = 0
    else:
        asset_turnover = np.inf

    if row['current_ratio_lag'] > 1:
        current_ratio = 1
    elif row['current_ratio_lag'] < 1:
        current_ratio = 0
    else:
        current_ratio = np.inf

    if row['quick_ratio_lag'] > 1:
        quick_ratio = 1
    elif row['quick_ratio_lag'] < 1:
        quick_ratio = 0
    else:
        quick_ratio = np.inf

    if row['interest_coverage_lag'] > 1:
        interest_coverage = 1
    elif row['interest_coverage_lag'] < 1:
        interest_coverage = 0
    else:
        interest_coverage = np.inf

    return roe + roi + debt_equity + cash_flow + sales_growth + asset_turnover + current_ratio + quick_ratio + interest_coverage

merged_data['piotroski_f_score'] = merged_data.apply(compute_piotroski_f_score, axis=1)

# Filter for highest book-to-market quintile
merged_data['book_to_market'] = np.log(merged_data['marketcap'] / merged_data['equity'])
merged_data['quintile'] = pd.qcut(merged_data['book_to_market'], q=5, labels=False)
merged_data = merged_data[merged_data['quintile'] == 4]

# Compute returns
merged_data['return'] = np.log(merged_data['closeadj'] / merged_data['closeadj'].shift(1))

# Save returns
merged_data.to_csv('returns.csv', columns=['date', 'return'], index=False)

# Print backtest complete
print("Backtest complete. Rows:", len(merged_data))

# Print first/last 5 rows
print(merged_data.head(5))
print(merged_data.tail(5))
